12	 * batchKey 与批号 batchNo。子批键已存在或请求内重复时整次 409，父批不变。
13	 */
14	public record SplitRequest(
15	        @NotBlank(message = "commandKey 不能为空") String commandKey,
16	        @NotNull(message = "children 不能为空")
17	        @Size(min = 2, max = 5, message = "children 必须包含 2～5 个子批")
18	        List<@Valid ChildSpec> children
19	) {
20	
21	    /**
22	     * 子批规格：batchKey 全局唯一，batchNo 为子批批号；产品编码、生产时间与必做检验项继承父批。
23	     */
24	    public record ChildSpec(
25	            @NotBlank(message = "子批 batchKey 不能为空") String batchKey,
26	            @NotBlank(message = "子批 batchNo 不能为空") String batchNo
