package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.util.List;

/**
 * 批次产率登记/修订请求。一个请求可含多个批次条目：先校验全部条目应用后的最终分配，
 * 再在单事务写入，任一失败整单回滚。yieldKey 为幂等键，指纹含操作者、expectedVersion、
 * 规范化批次集合和全部数值；同键成功重放首次快照，失败不占键。
 */
public record SubmitYieldRequest(
        @NotBlank(message = "yieldKey 不能为空") String yieldKey,
        @NotNull(message = "entries 不能为空")
        @Size(min = 1, max = 20, message = "entries 必须包含 1～20 个批次条目")
        List<@Valid YieldEntry> entries
) {

    /**
     * 单批次产率条目。expectedVersion 为空表示新登记（批次不得已有产率记录）；
     * 非空表示修订，必须与当前版本一致。投入/产出均大于零且最多三位小数。
     */
    public record YieldEntry(
            @NotBlank(message = "batchKey 不能为空") String batchKey,
            @Min(value = 1, message = "expectedVersion 必须大于等于 1") Long expectedVersion,
            @NotNull(message = "inputQuantity 不能为空")
            @DecimalMin(value = "0", inclusive = false, message = "inputQuantity 必须大于零")
            @Digits(integer = 13, fraction = 3, message = "inputQuantity 最多三位小数")
            BigDecimal inputQuantity,
            @NotNull(message = "outputQuantity 不能为空")
            @DecimalMin(value = "0", inclusive = false, message = "outputQuantity 必须大于零")
            @Digits(integer = 13, fraction = 3, message = "outputQuantity 最多三位小数")
            BigDecimal outputQuantity
    ) {
    }
}

package com.example.starter.batch.dto;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 单批次产率记录视图。inputQuantity/outputQuantity 为保留的原始数值；
 * yieldRate 为产出/投入按四位小数（HALF_UP）展示的产率；version 为当前记录版本。
 */
public record YieldEntryResponse(
        String batchKey,
        BigDecimal inputQuantity,
        BigDecimal outputQuantity,
        BigDecimal yieldRate,
        long version,
        String operatorId,
        Instant updatedAt
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 产率登记/修订响应：整单在单事务内落定，entries 为各批次最终记录视图。
 * submittedAt 为 UTC instant。
 */
public record SubmitYieldResponse(
        String yieldKey,
        List<YieldEntryResponse> entries,
        Instant submittedAt
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

/**
 * 批次产率查询响应。yield 为该批次产率记录，未登记时为 null；
 * recallBlock 为召回阻断原因（批次自身被召回或其血缘闭包内祖先被召回），无阻断为 null。
 */
public record BatchYieldResponse(
        String batchKey,
        BatchStatus status,
        YieldEntryResponse yield,
        RecallBlock recallBlock
) {

    /**
     * 召回阻断原因。direct 为 true 表示批次自身被直接召回；
     * false 表示血缘闭包内祖先被召回。已登记的产率记录不删除，仅阻断新增/修订。
     */
    public record RecallBlock(
            String recalledBatchKey,
            String reason,
            boolean direct
    ) {
    }
}

package com.example.starter.batch.dto;

import java.math.BigDecimal;
import java.util.List;

/**
 * 父子分配汇总查询响应。作为父批：outputQuantity 为本批已登记产出量（未登记为 null），
 * allocatedQuantity 为全部直接子批已登记投入量之和，remainingQuantity 为产出减已分配
 * （本批未登记产出时为 null）。作为子批：parent 给出直接父批的同一组汇总，无父批为 null。
 */
public record YieldAllocationResponse(
        String batchKey,
        BigDecimal outputQuantity,
        BigDecimal allocatedQuantity,
        BigDecimal remainingQuantity,
        ParentAllocation parent,
        List<ChildAllocation> children
) {

    /**
     * 直接父批的分配汇总。
     */
    public record ParentAllocation(
            String batchKey,
            java.math.BigDecimal outputQuantity,
            java.math.BigDecimal allocatedQuantity,
            java.math.BigDecimal remainingQuantity
    ) {
    }

    /**
     * 直接子批的已登记投入量；未登记产率的子批 inputQuantity 为 null。
     */
    public record ChildAllocation(
            String batchKey,
            java.math.BigDecimal inputQuantity
    ) {
    }
}

