        submitYield("op", "YK-RP-1", List.of(entryJson(parent, null, "110", "100")), 201);
        submitYield("op", "YK-RP-2", List.of(entryJson(c1, null, "60", "58")), 201);

        // 修订父批产出量到 50 < 已分配 60 → 422
        MvcResult rejected = submitYield("op", "YK-RP-3",
